+
+  <script type="module">
+    import * as THREE from 'three';
+    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
+    import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
+    import * as CANNON from 'cannon-es';
+
+    // Mandatory default values
+    const MANDATORY_DEFAULTS = Object.freeze({
+      impactSpeed: 22,
+      carMass: 1250,
+      carLength: 4.2,
+      carWidth: 1.8,
+      carHeight: 1.45,
+      wallCols: 12,
+      wallRows: 8,
+      wallDepth: 2,
+      brickMass: 2.5,
+      brickWidth: 0.50,
+      brickHeight: 0.24,
+      brickDepth: 0.20,
+      gravity: 9.81,
+      brickFriction: 0.72,
+      brickRestitution: 0.18,
+      groundFriction: 0.85,
+      trackLength: 40
+    });
+
+    // Deterministic seeded PRNG (Mulberry32) - never used to alter physics setup, only textures/visual variation
+    function createSeededRandom(seed = 1337420) {
+      let a = seed >>> 0;
+      return function () {
+        let t = (a += 0x6D2B79F5);
+        t = Math.imul(t ^ (t >>> 15), t | 1);
+        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
+        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+      };
+    }
+
+    // Collision filter groups
+    const GROUP_GROUND = 1;
+    const GROUP_BRICK = 2;
+    const GROUP_CAR_CORE = 4;
+    const GROUP_CAR_PANEL = 8;
+    const GROUP_CAR_WHEEL = 16;
+    const GROUP_CAR_GLASS = 32;
+
+    // Renderer & Scene Setup
+    const canvas = document.getElementById('viewport');
+    const renderer = new THREE.WebGLRenderer({
+      canvas,
+      antialias: true,
+      powerPreference: 'high-performance'
+    });
+    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
+    renderer.setSize(window.innerWidth, window.innerHeight);
+    renderer.shadowMap.enabled = true;
+    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
+    renderer.toneMapping = THREE.ACESFilmicToneMapping;
+    renderer.toneMappingExposure = 1.08;
+
+    const scene = new THREE.Scene();
+    scene.background = new THREE.Color(0x161d29);
+    scene.fog = new THREE.FogExp2(0x161d29, 0.0085);
+
+    const pmremGenerator = new THREE.PMREMGenerator(renderer);
+    scene.environment = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;
+    pmremGenerator.dispose();
+
+    // Camera & OrbitControls
+    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.15, 220);
+    const orbitControls = new OrbitControls(camera, renderer.domElement);
+    orbitControls.enableDamping = true;
+    orbitControls.dampingFactor = 0.08;
+    orbitControls.maxPolarAngle = Math.PI * 0.49;
+    orbitControls.minDistance = 2.0;
+    orbitControls.maxDistance = 85.0;
+    orbitControls.enabled = false;
+
+    // Lighting: Single crisp Directional Sun Light with tight shadow frustum + hemisphere fill
+    const hemiLight = new THREE.HemisphereLight(0xdbeafe, 0x1e293b, 0.45);
+    scene.add(hemiLight);
+
+    const sunLight = new THREE.DirectionalLight(0xfff7ed, 2.5);
+    sunLight.position.set(14, 24, 16);
+    sunLight.castShadow = true;
+    sunLight.shadow.mapSize.width = 2048;
+    sunLight.shadow.mapSize.height = 2048;
+    sunLight.shadow.camera.near = 2;
+    sunLight.shadow.camera.far = 75;
+    sunLight.shadow.bias = -0.00035;
+    sunLight.shadow.normalBias = 0.015;
+    scene.add(sunLight);
+    scene.add(sunLight.target);
+
+    // Procedural Textures (Asphalt, Grass/Gravel, Contact Shadow Blob)
+    function makeAsphaltTexture() {
+      const c = document.createElement('canvas');
+      c.width = 512;
+      c.height = 512;
+      const ctx = c.getContext('2d');
+      const rng = createSeededRandom(9001);
+      ctx.fillStyle = '#22262e';
+      ctx.fillRect(0, 0, 512, 512);
+      for (let i = 0; i < 18000; i++) {
+        const x = Math.floor(rng() * 512);
+        const y = Math.floor(rng() * 512);
+        const v = Math.floor(24 + rng() * 34);
+        ctx.fillStyle = `rgb(${v},${v + 2},${v + 5})`;
+        ctx.fillRect(x, y, 2, 2);
+      }
+      const tex = new THREE.CanvasTexture(c);
+      tex.wrapS = THREE.RepeatWrapping;
+      tex.wrapT = THREE.RepeatWrapping;
+      tex.anisotropy = 4;
+      return tex;
+    }
+
+    function makeContactBlobTexture() {
+      const c = document.createElement('canvas');
+      c.width = 128;
+      c.height = 128;
+      const ctx = c.getContext('2d');
+      const grad = ctx.createRadialGradient(64, 64, 6, 64, 64, 62);
+      grad.addColorStop(0, 'rgba(0, 0, 0, 0.55)');
+      grad.addColorStop(0.55, 'rgba(0, 0, 0, 0.25)');
+      grad.addColorStop(1, 'rgba(0, 0, 0, 0.0)');
+      ctx.fillStyle = grad;
+      ctx.fillRect(0, 0, 128, 128);
+      return new THREE.CanvasTexture(c);
+    }
+
+    const asphaltTex = makeAsphaltTexture();
+    const contactBlobTex = makeContactBlobTexture();
+
+    // Shared Materials
+    const materials = {
+      asphalt: new THREE.MeshStandardMaterial({
+        map: asphaltTex,
+        roughness: 0.88,
+        metalness: 0.05
+      }),
+      shoulder: new THREE.MeshStandardMaterial({
+        color: 0x263124,
+        roughness: 0.96,
+        metalness: 0.0
+      }),
+      curbRed: new THREE.MeshStandardMaterial({ color: 0xb91c1c, roughness: 0.7 }),
+      curbWhite: new THREE.MeshStandardMaterial({ color: 0xe2e8f0, roughness: 0.7 }),
