+    // Build Freestanding Staggered Running-Bond Brick Wall
+    function buildBrickWall(cfg, brickPhysMat) {
+      const cols = cfg.wallCols;
+      const rows = cfg.wallRows;
+      const depthLayers = cfg.wallDepth;
+      const bw = cfg.brickWidth;
+      const bh = cfg.brickHeight;
+      const bd = cfg.brickDepth;
+      const bMass = cfg.brickMass;
+
+      // Visual mortar gap so every brick and bond line reads clearly
+      const visualGap = 0.008;
+      const meshW = Math.max(0.04, bw - visualGap);
+      const meshH = Math.max(0.04, bh - visualGap);
+      const meshD = Math.max(0.04, bd - visualGap);
+      const brickGeo = new THREE.BoxGeometry(meshD, meshH, meshW);
+
+      // Physics half-extents: exact height so rows stack flush without vertical bounce, tiny horizontal clearance
+      const physHalfX = (bd - 0.002) * 0.5;
+      const physHalfY = bh * 0.5;
+      const physHalfZ = (bw - 0.002) * 0.5;
+      const brickShape = new CANNON.Box(new CANNON.Vec3(physHalfX, physHalfY, physHalfZ));
+
+      const colorRng = createSeededRandom(77123);
+      const totalDepthSpan = depthLayers * bd;
+      const firstLayerX = wallX - totalDepthSpan * 0.5 + bd * 0.5;
+
+      for (let d = 0; d < depthLayers; d++) {
+        const bx = firstLayerX + d * bd;
+        for (let r = 0; r < rows; r++) {
+          const by = physHalfY + r * bh;
+          // Staggered running bond: alternate rows offset by half a brick width
+          const staggerOffset = (r + d) % 2 === 1 ? bw * 0.25 : -bw * 0.25;
+          const rowStartZ = -((cols - 1) * bw) * 0.5 + staggerOffset;
+
+          for (let c = 0; c < cols; c++) {
+            const bz = rowStartZ + c * bw;
+            const matIdx = Math.floor(colorRng() * brickMaterials.length);
+            const mesh = new THREE.Mesh(brickGeo, brickMaterials[matIdx]);
+            mesh.castShadow = true;
+            mesh.receiveShadow = true;
+            mesh.position.set(bx, by, bz);
+
+            const body = new CANNON.Body({
+              mass: bMass,
+              material: brickPhysMat,
+              shape: brickShape,
+              linearDamping: 0.03,
+              angularDamping: 0.08,
+              allowSleep: true,
+              sleepSpeedLimit: 0.12,
+              sleepTimeLimit: 0.15,
+              collisionFilterGroup: GROUP_BRICK,
+              collisionFilterMask:
+                GROUP_GROUND |
+                GROUP_BRICK |
+                GROUP_CAR_CORE |
+                GROUP_CAR_PANEL |
+                GROUP_CAR_WHEEL |
+                GROUP_CAR_GLASS
+            });
+            body.position.set(bx, by, bz);
+            // Start bricks asleep so freestanding wall is rock-solid until hit
+            body.sleep();
+
+            registerRigidEntity(body, mesh, { isBrick: true, partName: 'brick' });
+          }
+        }
+      }
+    }
