+        const mesh = new THREE.Mesh(dustGeo, materials.dust);
+        mesh.position.set(
+          originX + (fxRng() - 0.5) * 1.4,
+          Math.max(0.2, originY + (fxRng() - 0.4) * 1.1),
+          originZ + (fxRng() - 0.5) * 2.2
+        );
+        dynamicGroup.add(mesh);
+        particles.push({
+          mesh,
+          vx: (fxRng() - 0.3) * 4.5,
+          vy: 1.0 + fxRng() * 3.2,
+          vz: (fxRng() - 0.5) * 5.0,
+          life: 0.9 + fxRng() * 0.9,
+          maxLife: 1.8,
+          isSpark: false
+        });
+      }
+    }
+
+    // Rebuild / Reset Entire Simulation from Settings
+    function rebuildSimulation() {
+      if (dynamicGroup) {
+        scene.remove(dynamicGroup);
+        dynamicGroup.traverse((obj) => {
+          if (obj.geometry && obj.geometry !== tireGeoShared) {
+            // Dispose one-off geometries safely
+          }
+        });
+      }
+
+      dynamicGroup = new THREE.Group();
+      scene.add(dynamicGroup);
+
+      syncedPairs = [];
+      breakableJoints = [];
+      particles = [];
+      skidSegments = [];
+      lastWheelSkidPos = [null, null, null, null];
+      detachedCount = 0;
+      simClock = 0;
+      accumulator = 0;
+      firstImpactOccurred = false;
+      impactTime = -1;
+      cameraShakeIntensity = 0;
+      fxRng = createSeededRandom(424242);
+
+      const cfg = currentSettings;
+
+      // Position car start and freestanding brick wall along the track
+      wallX = cfg.trackLength * 0.24;
+      startX = -cfg.trackLength * 0.36;
+
+      // Update shadow camera frustum tightly around track, car, and wall
+      const frustumSpan = Math.max(18, cfg.trackLength * 0.52);
+      sunLight.position.set(wallX - 6, 22, 15);
+      sunLight.target.position.set(wallX - 2, 0, 0);
+      sunLight.shadow.camera.left = -frustumSpan;
+      sunLight.shadow.camera.right = frustumSpan * 0.85;
+      sunLight.shadow.camera.top = 16;
+      sunLight.shadow.camera.bottom = -16;
+      sunLight.shadow.camera.updateProjectionMatrix();
+
+      // Initialize Cannon-es World
+      world = new CANNON.World();
+      world.gravity.set(0, -cfg.gravity, 0);
+      world.broadphase = new CANNON.SAPBroadphase(world);
+      world.allowSleep = true;
+      world.solver.iterations = 14;
+      world.solver.tolerance = 0.0005;
+
+      const groundPhysMat = new CANNON.Material('ground');
+      const brickPhysMat = new CANNON.Material('brick');
+      const carPhysMat = new CANNON.Material('car');
+      const wheelPhysMat = new CANNON.Material('wheel');
+      const glassPhysMat = new CANNON.Material('glass');
+
+      // Contact Materials wired to settings
+      world.addContactMaterial(
+        new CANNON.ContactMaterial(groundPhysMat, brickPhysMat, {
+          friction: cfg.groundFriction,
+          restitution: cfg.brickRestitution
+        })
+      );
+      world.addContactMaterial(
+        new CANNON.ContactMaterial(brickPhysMat, brickPhysMat, {
+          friction: cfg.brickFriction,
+          restitution: cfg.brickRestitution
+        })
+      );
+      world.addContactMaterial(
+        new CANNON.ContactMaterial(carPhysMat, brickPhysMat, {
+          friction: cfg.brickFriction * 0.7,
+          restitution: cfg.brickRestitution
+        })
+      );
+      world.addContactMaterial(
+        new CANNON.ContactMaterial(carPhysMat, groundPhysMat, {
+          friction: cfg.groundFriction * 0.75,
+          restitution: 0.1
+        })
+      );
+      world.addContactMaterial(
+        new CANNON.ContactMaterial(wheelPhysMat, groundPhysMat, {
+          friction: cfg.groundFriction * 0.9,
+          restitution: 0.05
+        })
+      );
+      world.addContactMaterial(
+        new CANNON.ContactMaterial(glassPhysMat, groundPhysMat, {
+          friction: cfg.groundFriction * 0.5,
+          restitution: 0.25
+        })
+      );
+
+      // Ground Physics Plane
+      const groundBody = new CANNON.Body({
+        mass: 0,
+        material: groundPhysMat,
+        shape: new CANNON.Plane(),
+        collisionFilterGroup: GROUP_GROUND,
+        collisionFilterMask:
+          GROUP_BRICK | GROUP_CAR_CORE | GROUP_CAR_PANEL | GROUP_CAR_WHEEL | GROUP_CAR_GLASS
+      });
+      groundBody.quaternion.setFromEuler(-Math.PI / 2, 0, 0);
+      world.addBody(groundBody);
+
+      buildTrackEnvironment(cfg);
+      buildBrickWall(cfg, brickPhysMat);
+      buildCar(cfg, carPhysMat, wheelPhysMat, glassPhysMat);
+
+      // Detect first impact with wall to cut engine drive and trigger impact effects
+      const onPreImpactCollide = (e) => {
+        const other = e.body;
+        if (!other) return;
+        if (other.collisionFilterGroup === GROUP_BRICK) {
+          if (!firstImpactOccurred) {
+            firstImpactOccurred = true;
+            impactTime = simClock;
+            const relV = Math.hypot(
+              cabinBody.velocity.x - other.velocity.x,
+              cabinBody.velocity.y - other.velocity.y,
+              cabinBody.velocity.z - other.velocity.z
+            );
+            cameraShakeIntensity = Math.min(0.45, (relV / 22) * 0.24);
+            spawnImpactParticles(
+              frontNoseBody.position.x + 0.3,
+              frontNoseBody.position.y,
+              frontNoseBody.position.z,
+              Math.max(0.6, relV / 18)
+            );
+          }
+        }
+      };
+
+      frontNoseBody.addEventListener('collide', onPreImpactCollide);
+      frontClipBody.addEventListener('collide', onPreImpactCollide);
+      cabinBody.addEventListener('collide', onPreImpactCollide);
+
+      updateCameraView(true);
+      updateTelemetryUI();
+    }
+
+    const tireGeoShared = null;
+
+    // Step Fixed Physics & Evaluate Breakable Constraints
+    function stepSimulation(dt) {
+      const cfg = currentSettings;
+
+      // Before impact: maintain target impact speed so the car reaches the wall at exact configured speed
+      if (!firstImpactOccurred && cabinBody) {
+        const currentVx = cabinBody.velocity.x;
+        const speedError = cfg.impactSpeed - currentVx;
+        const driveAccel = speedError * 14.0;
+        cabinBody.applyForce(new CANNON.Vec3(cabinBody.mass * driveAccel, 0, 0), cabinBody.position);
+        frontClipBody.applyForce(new CANNON.Vec3(frontClipBody.mass * driveAccel, 0, 0), frontClipBody.position);
+
+        // Keep car tracking straight down centerline before impact
+        cabinBody.velocity.z *= 0.85;
+        cabinBody.angularVelocity.y *= 0.85;
+
+        // Check proximity to wall face to wake bricks right before contact so no tunneling occurs
+        const noseFrontX = frontNoseBody.position.x + cfg.carLength * 0.1;
+        if (noseFrontX >= wallX - cfg.wallDepth * cfg.brickDepth - 0.9) {
+          for (let i = 0; i < syncedPairs.length; i++) {
+            const p = syncedPairs[i];
+            if (p.isBrick && p.body.sleepState !== CANNON.Body.AWAKE) {
+              p.body.wakeUp();
+            }
+          }
+        }
+      }
+
+      world.step( dt );
+      simClock += dt;
+
+      // Evaluate breakable constraints based on solver equation multipliers & impact deceleration
+      if (firstImpactOccurred || simClock > 0.08) {
+        // Measure instantaneous deceleration/shock on front clip & cabin
+        const impactShock = firstImpactOccurred
+          ? Math.max(0, (cfg.impactSpeed - cabinBody.velocity.x) * (cfg.carMass / 1250) * 6.8)
+          : 0;
+
+        for (let i = breakableJoints.length - 1; i >= 0; i--) {
+          const j = breakableJoints[i];
+          const eqs = j.constraint.equations;
+          let maxMult = 0;
+          for (let k = 0; k < eqs.length; k++) {
+            const m = Math.abs(eqs[k].multiplier);
+            if (m > maxMult) maxMult = m;
+          }
+
+          const effectiveLoad = maxMult + impactShock;
+
+          if (j.stage === 0 && effectiveLoad > j.threshold) {
+            world.removeConstraint(j.constraint);
+            if (j.onBreakStage1) j.onBreakStage1();
+
+            if (j.secondaryConstraint) {
+              j.stage = 1;
+            } else {
+              j.entry.detached = true;
+              detachedCount++;
+              breakableJoints.splice(i, 1);
+            }
+
+            if (firstImpactOccurred && particles.length < 70) {
+              spawnImpactParticles(
+                j.entry.body.position.x,
+                j.entry.body.position.y,
+                j.entry.body.position.z,
+                0.35
+              );
+            }
+          } else if (j.stage === 1 && j.secondaryConstraint) {
+            const eqs2 = j.secondaryConstraint.equations;
+            let maxMult2 = 0;
+            for (let k = 0; k < eqs2.length; k++) {
+              const m2 = Math.abs(eqs2[k].multiplier);
+              if (m2 > maxMult2) maxMult2 = m2;
+            }
+            if (maxMult2 + impactShock * 0.85 > j.secondaryThreshold) {
+              world.removeConstraint(j.secondaryConstraint);
+              if (j.onBreakStage2) j.onBreakStage2();
+              j.entry.detached = true;
+              detachedCount++;
+              breakableJoints.splice(i, 1);
+            }
+          }
+        }
+      }
+
+      // Leave tire skid marks on asphalt after impact when wheels slide laterally or decelerate hard
+      if (firstImpactOccurred && skidSegments.length < 140) {
+        const skidGeo = new THREE.PlaneGeometry(0.32, 0.22);
+        skidGeo.rotateX(-Math.PI / 2);
+        for (let w = 0; w < wheelBodies.length; w++) {
+          const wb = wheelBodies[w];
+          if (wb.body.position.y < wb.radius * 1.35) {
+            const pos = wb.body.position;
+            const prev = lastWheelSkidPos[w];
+            if (!prev || Math.hypot(pos.x - prev.x, pos.z - prev.z) > 0.26) {
+              const mark = new THREE.Mesh(skidGeo, materials.skidMark);
+              mark.position.set(pos.x, 0.0035, pos.z);
+              dynamicGroup.add(mark);
+              skidSegments.push(mark);
+              lastWheelSkidPos[w] = { x: pos.x, z: pos.z };
+            }
+          }
+        }
+      }
+
+      // Step visual particles
+      for (let i = particles.length - 1; i >= 0; i--) {
+        const pt = particles[i];
+        pt.life -= dt;
+        if (pt.life <= 0) {
+          dynamicGroup.remove(pt.mesh);
+          particles.splice(i, 1);
+          continue;
+        }
+        if (pt.isSpark) {
+          pt.vy -= cfg.gravity * dt;
+        } else {
+          pt.vx *= 0.96;
+          pt.vz *= 0.96;
+          const s = 1 + (1 - pt.life / pt.maxLife) * 2.2;
+          pt.mesh.scale.setScalar(s);
+        }
+        pt.mesh.position.x += pt.vx * dt;
+        pt.mesh.position.y = Math.max(0.05, pt.mesh.position.y + pt.vy * dt);
+        pt.mesh.position.z += pt.vz * dt;
+      }
+
+      // Decay brief camera shake
+      if (cameraShakeIntensity > 0.001) {
+        cameraShakeIntensity *= Math.pow(0.04, dt);
+      } else {
+        cameraShakeIntensity = 0;
+      }
+    }
+
+    // Sync Three.js Meshes & Contact Shadow Blobs with Cannon Bodies
+    function syncVisuals() {
+      for (let i = 0; i < syncedPairs.length; i++) {
+        const item = syncedPairs[i];
+        const b = item.body;
+        const m = item.mesh;
+        m.position.copy(b.position);
+        m.quaternion.copy(b.quaternion);
+
+        if (item.blob) {
+          const h = Math.max(0, b.position.y - 0.15);
+          const fade = Math.max(0, 1 - h / 2.6);
+          item.blob.position.x = b.position.x;
+          item.blob.position.z = b.position.z;
+          item.blob.visible = fade > 0.05;
+        }
+      }
+
+      if (carMainShadowBlob && cabinBody) {
+        carMainShadowBlob.position.x = cabinBody.position.x + currentSettings.carLength * 0.08;
+        carMainShadowBlob.position.z = cabinBody.position.z;
+        const euler = new THREE.Euler().setFromQuaternion(cabinBody.quaternion, 'YXZ');
+        carMainShadowBlob.rotation.y = euler.y;
+      }
+    }
+
+    // Update Camera Rig (Impact, Follow, Top, Orbit)
+    const camTarget = new THREE.Vector3();
+    const desiredCamPos = new THREE.Vector3();
+
+    function updateCameraView(instant = false) {
+      if (!cabinBody) return;
+      const carPos = cabinBody.position;
+
+      // Subtle deterministic camera shake offset on impact
+      const shakeX = cameraShakeIntensity * Math.sin(simClock * 58);
+      const shakeY = cameraShakeIntensity * Math.cos(simClock * 73);
+
+      if (cameraMode === 'impact') {
+        orbitControls.enabled = false;
+        // Three-quarter cinematic shot showing car, track, and wall, holding a readable frame of the breakup
+        const focusX = THREE.MathUtils.lerp(carPos.x + 2.5, wallX - 0.5, 0.68);
+        camTarget.set(focusX + shakeX, 1.05 + shakeY, 0);
+        desiredCamPos.set(wallX - 6.8, 3.1, 8.8);
+        if (instant) {
+          camera.position.copy(desiredCamPos);
+        } else {
+          camera.position.lerp(desiredCamPos, 0.08);
+        }
+        camera.lookAt(camTarget);
+      } else if (cameraMode === 'follow') {
+        orbitControls.enabled = false;
+        // Chase the car through approach and hold both car and collapsing wall inside frame at impact
+        const clampedCarX = Math.min(carPos.x, wallX + 2.5);
+        desiredCamPos.set(clampedCarX - 6.8, 2.55 + shakeY, 2.6);
+        camTarget.set(
+          Math.max(carPos.x + 3.2, wallX - 0.6) + shakeX,
+          1.1 + shakeY,
+          carPos.z * 0.4
+        );
+        if (instant) {
+          camera.position.copy(desiredCamPos);
+        } else {
+          camera.position.lerp(desiredCamPos, 0.12);
+        }
+        camera.lookAt(camTarget);
+      } else if (cameraMode === 'top') {
+        orbitControls.enabled = false;
+        // Straight overhead view of the track and wall
+        const centerFocusX = (startX + wallX) * 0.25 + 2.0;
+        const height = Math.max(24, currentSettings.trackLength * 0.72);
+        camera.position.set(centerFocusX, height, 0.01);
+        camera.lookAt(centerFocusX, 0, 0);
+      } else if (cameraMode === 'orbit') {
+        orbitControls.enabled = true;
+        if (instant) {
+          camera.position.set(wallX - 7.5, 4.2, 9.5);
+          orbitControls.target.set(wallX - 1.5, 1.1, 0);
+        }
+        orbitControls.update();
+      }
+    }
+
+    function updateTelemetryUI() {
+      elTime.textContent = simClock.toFixed(2);
+      const spd = cabinBody ? cabinBody.velocity.length() : 0;
+      elSpeed.textContent = spd.toFixed(1);
+      elJoints.textContent = `${breakableJoints.length}/${totalInitialJoints}`;
+      elDebris.textContent = `${detachedCount}`;
+    }
+
+    // UI Event Listeners
+    function setPlayState(playing) {
+      isPlaying = playing;
+      btnPlayPause.textContent = isPlaying ? 'Pause' : 'Play';
+      btnPlayPause.classList.toggle('active', !isPlaying);
+    }
+
+    btnPlayPause.addEventListener('click', () => {
+      setPlayState(!isPlaying);
+    });
+
+    btnReplay.addEventListener('click', () => {
+      currentSettings = readSettingsFromInputs();
+      writeSettingsToInputs(currentSettings);
+      rebuildSimulation();
+      setPlayState(true);
+    });
+
+    btnApply.addEventListener('click', () => {
+      currentSettings = readSettingsFromInputs();
+      writeSettingsToInputs(currentSettings);
+      rebuildSimulation();
+      setPlayState(true);
+    });
+
+    btnResetDefaults.addEventListener('click', () => {
+      currentSettings = { ...MANDATORY_DEFAULTS };
+      writeSettingsToInputs(currentSettings);
+      rebuildSimulation();
+      setPlayState(true);
+    });
+
+    btnToggleSettings.addEventListener('click', () => {
+      const collapsed = settingsPanel.classList.toggle('collapsed');
+      btnToggleSettings.classList.toggle('active', !collapsed);
+    });
+
+    btnCloseSettings.addEventListener('click', () => {
+      settingsPanel.classList.add('collapsed');
+      btnToggleSettings.classList.remove('active');
+    });
+
+    document.getElementById('speed-group').addEventListener('click', (e) => {
+      const btn = e.target.closest('button[data-speed]');
+      if (!btn) return;
+      simSpeed = parseFloat(btn.dataset.speed);
+      document.querySelectorAll('#speed-group button').forEach((b) => b.classList.toggle('active', b === btn));
+    });
+
+    document.getElementById('camera-group').addEventListener('click', (e) => {
+      const btn = e.target.closest('button[data-cam]');
+      if (!btn) return;
+      cameraMode = btn.dataset.cam;
+      document.querySelectorAll('#camera-group button').forEach((b) => b.classList.toggle('active', b === btn));
+      orbitHint.classList.toggle('visible', cameraMode === 'orbit');
+      updateCameraView(true);
+    });
+
+    window.addEventListener('keydown', (e) => {
+      if (e.code === 'Space') {
+        const active = document.activeElement;
+        if (active && active.tagName === 'INPUT') return;
+        e.preventDefault();
+        setPlayState(!isPlaying);
+      }
+    });
+
+    window.addEventListener('resize', () => {
+      camera.aspect = window.innerWidth / window.innerHeight;
+      camera.updateProjectionMatrix();
+      renderer.setSize(window.innerWidth, window.innerHeight);
+    });
+
+    // Initialize First Run Automatically with Mandatory Defaults at 1x Playing
+    writeSettingsToInputs(MANDATORY_DEFAULTS);
+    rebuildSimulation();
+
+    // Main Render & Fixed-Step Physics Loop
+    let lastFrameTime = performance.now();
+
+    function animate(now) {
+      requestAnimationFrame(animate);
+
+      const rawDt = Math.min(0.05, (now - lastFrameTime) / 1000);
+      lastFrameTime = now;
+
+      if (isPlaying) {
+        accumulator += rawDt * simSpeed;
+        // Cap steps per frame so a hitch cannot explode the solver
+        const maxSteps = 10;
+        let steps = 0;
+        while (accumulator >= FIXED_DT && steps < maxSteps) {
+          stepSimulation(FIXED_DT);
+          accumulator -= FIXED_DT;
+          steps++;
+        }
+        if (steps === maxSteps) {
+          accumulator = 0;
+        }
+        syncVisuals();
+        updateTelemetryUI();
+      }
+
+      updateCameraView(false);
+      renderer.render(scene, camera);
+    }
+
+    requestAnimationFrame(animate);
+  </script>
+</body>
+</html>
